using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using OwnLabView;
class ReadMixedProject {
 [STAThread]static int Main(string[] a){typeof(Storage).GetField("Root").SetValue(null,a[0]);object app=null,project=null;var refs=new List<object>();try{
 var report=Data.Map(Data.Json.DeserializeObject(File.ReadAllText(a[1])));string path=Data.Text(report,"project_path");var expected=Data.Array(report["xml_member_references"]).Select(Data.Map).Select(r=>Data.Text(r,"path")).ToArray();var hashes=expected.ToDictionary(p=>p,Data.Hash,StringComparer.OrdinalIgnoreCase);hashes[path]=Data.Hash(path);
 foreach(string cls in expected.Where(p=>Path.GetExtension(p)==".lvclass"))foreach(var entry in ClassSnapshot.Plan(cls).Sources)hashes[entry.Key]=entry.Value;
 using(var lease=new NiSessionLease()){app=Activator.CreateInstance(Type.GetTypeFromProgID("LabVIEW.Application",true));lease.Attached();project=LabView.Invoke(app,"OpenProject",BindingFlags.InvokeMethod,path);object computer=LabView.Invoke(project,"MyComputer",BindingFlags.GetProperty);refs.Add(computer);var actual=new List<object>();var paths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
 var parents=new Queue<object>();parents.Enqueue(computer);while(parents.Count>0)foreach(object item in (IEnumerable)LabView.Invoke(parents.Dequeue(),"Children",BindingFlags.GetProperty)){refs.Add(item);string kind=Convert.ToString(LabView.Invoke(item,"TypeString",BindingFlags.GetProperty));if(kind=="Folder"){parents.Enqueue(item);continue;}if(kind=="Dependencies"||kind=="Build")continue;string p=Convert.ToString(LabView.Invoke(item,"Path",BindingFlags.GetProperty));if(!new[]{".vi",".ctl",".lvclass",".lvlib"}.Contains(Path.GetExtension(p),StringComparer.OrdinalIgnoreCase))throw new IOException("Unexpected project item: "+kind);p=TypeImport.NativePath(p);paths.Add(p);actual.Add(new{path=p,type=kind});}
 if(!paths.SetEquals(expected))throw new IOException("Mixed project native member paths differ.");foreach(var entry in hashes)if(Data.Hash(entry.Key)!=entry.Value)throw new IOException("Project/member/dependency changed: "+entry.Key);
 Storage.WriteNew(a[2],new{passed=true,native_members=actual,checked_files=hashes,source_files_unchanged=true,window_operations_used=false,generated_vis_executed=false});
 }return 0;}catch(Exception e){Storage.WriteNew(a[2],new{passed=false,error=e.ToString()});return 1;}finally{for(int i=refs.Count-1;i>=0;i--)LabView.Release(refs[i]);if(project!=null)try{LabView.Invoke(project,"Close",BindingFlags.InvokeMethod);}catch{}LabView.Release(project);LabView.Release(app);}}
}
